import { createNerRecognizer, redactWithNer, regexDetector } from "maskera"

const recognizer = createNerRecognizer()

const caseIdDetector = regexDetector("EGENT", /\bÄRENDE-\d{4}-\d{4}\b/g)

const { text, restore } = await redactWithNer(
  "Patient Anna Lindqvist (19900101-2385) i ÄRENDE-2026-0412 fick 500 mg Alvedon.",
  {
    recognizer,
    profile: "clinical",
    detectors: [caseIdDetector],
  },
)

const answer = await callYourModel(text)
const finalReply = restore(answer)

